"""Exception definitions."""

from . import _utils

__all__ = export = _utils.ExportList()


@export
class JSILIBError(Exception):
    """Base class for exceptions that can be raised by this library."""
    __message_template__: str = None

    def __str__(self):
        if self.__message_template__ is None:
            return super().__str__()
        return self.__message_template__.format(self=self)
